<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {Play,Pause,RotateCcw,RefreshCw,ChevronLeft,ChevronRight} from '@lucide/vue';
import {assetApi} from '../api';
import {useI18n} from '../uiPorts';
import {refreshFeedback as vRefreshFeedback} from '../../../shared/directives/refreshFeedback';
import type {CleanupResearchError,SeedCleanup} from '../seeds/cleanup';
const props=defineProps<{projectId:number}>();
const emit=defineEmits<{changed:[]}>();
const {tr}=useI18n();
const data=ref<SeedCleanup>(),organization=ref(''),busy=ref(false),reading=ref(false),resultsReady=ref(false),error=ref(''),uncertain=ref(false),filter=ref('conflict'),page=ref(1);
let pendingOperation='',generation=0,sequence=0,controlSequence=0,disposed=false,timer:ReturnType<typeof setTimeout>|undefined;
const runId=computed(()=>data.value?.runId||data.value?.id);
const enabled=computed(()=>data.value?.enabled===true);
const counts=computed(()=>data.value?.counts||{});
const localReview=computed(()=>{const c=counts.value;const pending=c.pending||0;const done=(c.retained||0)+(c.excluded||0)+(c.evidence??c.needs_evidence??0)+(c.held||0)+(c.conflict||0)+(c.restored||0);return {pending,done,total:pending+done};});
const percent=computed(()=>{const s=data.value?.snapshot;return s?.total?Math.min(100,Math.round((s.processed||0)*100/s.total)):0;});
const pages=computed(()=>Math.max(1,Math.ceil((data.value?.total||0)/25)));
const labels:Record<string,[string,string]>={preparing:['整理全项目种子','Preparing all project seeds'],researching:['自动分析与联网补证','Researching evidence'],waiting_evidence:['已保存进度，等待公开来源重试','Progress saved; awaiting public-source retry'],paused:['已暂停，可继续','Paused; resumable'],analyzing:['AI 正在分析证据','AI evidence analysis'],completed:['本轮已完成','Round completed'],excluded:['已自动排除','Automatically excluded'],retained:['保留相关线索','Related leads retained'],evidence:['自动继续补证','Continuing evidence research'],held:['保留原决定或等待关联证据','Prior decision kept or awaiting related evidence'],needs_evidence:['自动继续补证','Continuing evidence research'],conflict:['证据冲突','Evidence conflict'],pending:['等待本地整理','Awaiting local classification'],restored:['已撤销排除','Exclusion undone'],idle:['尚未开始','Not started']};
function label(value?:string){return labels[value||'idle']?tr(...labels[value||'idle']):value;}
function number(value?:number){return typeof value==='number'?value.toLocaleString():tr('待统计','Pending');}
function researchLabel(kind:string){return ({dns_cname:tr('DNS / CNAME 记录','DNS / CNAME records'),ct_search:tr('公开 CT 名称查询','Public CT name search'),ct_certificate:tr('公开 CT 证书读取','Public CT certificate retrieval'),organization:tr('目标单位关系补证','Target organization research')} as Record<string,string>)[kind]||kind;}
function retryTime(value?:number|null){if(!value||!Number.isFinite(value))return '';const date=new Date(value*1000);return Number.isNaN(date.getTime())?'':date.toLocaleString(tr('zh-CN','en-US'),{hour12:false});}
function retryDescription(entry:CleanupResearchError){
 if(entry.state==='failed'||entry.state==='blocked')return tr('本项已保留，等待新的有效证据；不会据此排除','This item is retained pending new evidence; no exclusion follows from this error');
 const at=retryTime(entry.nextAt);
 if(!enabled.value)return tr('任务已暂停；继续后恢复补证','The run is paused; resume to continue research')+(at?tr(' · 下次重试时间：',' · Next retry time: ')+at:'');
 return at?tr('下次自动重试：','Next automatic retry: ')+at:tr('已保存断点，等待自动重试','Checkpoint saved; awaiting automatic retry');
}
function schedule(){clearTimeout(timer);if(enabled.value&&!disposed)timer=setTimeout(()=>void read(),2500);}
function accept(value:SeedCleanup,p:number,g:number,seq:number,queryResult=true){
 if(disposed||g!==generation||seq!==sequence||p!==props.projectId)return false;
 if(value.projectId!==p||value.items!==undefined&&!Array.isArray(value.items))throw Error('seed_cleanup_scope_mismatch');
 // Mutation receipts use the owner's default query. Only an explicit status
 // read with our filter/page may populate the visible result list.
 if(queryResult){data.value=value;resultsReady.value=true;}else{data.value={...value,items:[],total:data.value?.total??0,page:page.value,pageSize:25};resultsReady.value=false;}
 if(pendingOperation&&value.operation?.id===pendingOperation&&['completed','rejected'].includes(value.operation.state)){uncertain.value=false;pendingOperation='';}if(!organization.value.trim())organization.value=value.organization||'';return true;
}
async function read(){
 const p=props.projectId,g=generation,seq=++sequence;reading.value=true;
 try{const value=await assetApi.seedCleanup(p,'status',{...(runId.value?{runId:runId.value}:{}),...(pendingOperation?{operationId:pendingOperation}:{}),page:page.value,pageSize:25,filter:filter.value},`read-${p}`);if(accept(value,p,g,seq)){error.value='';schedule();}}
 catch(e){if(!disposed&&g===generation&&seq===sequence){error.value=String(e);schedule();}}
 finally{if(!disposed&&g===generation&&seq===sequence)reading.value=false;}
}
async function control(action:'start'|'pause'|'resume'|'restore'){
 if(busy.value||uncertain.value||action==='start'&&!organization.value.trim())return;
 const p=props.projectId,g=generation,seq=++sequence,controlSeq=++controlSequence;
 busy.value=true;error.value='';clearTimeout(timer);
 const operationId=globalThis.crypto.randomUUID();pendingOperation=operationId;
 const args=action==='start'?{organization:organization.value.trim(),autoExcludeUnrelated:true}:{runId:runId.value};
 try{const value=await assetApi.seedCleanup(p,action,args,operationId);if(accept(value,p,g,seq,false)){uncertain.value=value.outcomeUnknown===true;if(!uncertain.value)pendingOperation='';emit('changed');if(!uncertain.value)await read();else schedule();}}
 catch(e){if(!disposed&&g===generation&&seq===sequence){error.value=String(e);uncertain.value=!/^cleanup_(?:arguments_invalid|organization_invalid|project_already_running|run_project_mismatch|filter_invalid|action_invalid|trusted_operation_required)$/.test(String(e));if(!uncertain.value)pendingOperation='';}}
 finally{if(!disposed&&g===generation&&controlSeq===controlSequence)busy.value=false;}
}
async function changePage(next:number){if(reading.value||busy.value)return;const old=page.value;page.value=Math.max(1,Math.min(pages.value,next));await read();if(error.value)page.value=old;}
watch(filter,()=>{page.value=1;void read();});
watch(()=>props.projectId,()=>{pendingOperation='';generation++;sequence++;controlSequence++;clearTimeout(timer);data.value=undefined;organization.value='';busy.value=false;reading.value=false;resultsReady.value=false;error.value='';uncertain.value=false;page.value=1;void read();},{immediate:true,flush:'sync'});
onUnmounted(()=>{disposed=true;generation++;sequence++;controlSequence++;clearTimeout(timer);});
</script>
<template>
<section class="cleanup-panel" data-testid="seed-cleanup-panel" :aria-busy="busy||reading">
 <header><div><h3>{{tr('AI 清洗项目种子','AI project seed cleanup')}}</h3><p>{{tr('先结合本地证书、备案和已有审核判断；缺证项自动补查公开来源，真正冲突才集中审核。','Classify saved certificates, registrations and prior reviews first; research missing public evidence automatically and group genuine conflicts for review.')}}</p></div><button v-refresh-feedback="{scope:projectId,busy:reading,error}" class="button ghost compact" :disabled="busy||reading" data-cleanup-action="refresh" @click="read"><RefreshCw :size="14"/>{{tr('刷新进度','Refresh progress')}}</button></header>
 <div class="cleanup-start"><label>{{tr('目标单位与业务范围','Target organization and scope')}}<input v-model="organization" maxlength="240" :disabled="enabled||busy||!!runId" :placeholder="tr('例如：中国移动集团及其下属单位','For example: organization and subsidiaries')"/></label><button v-if="!runId" class="button primary compact" :disabled="busy||uncertain||!organization.trim()" data-cleanup-action="start" @click="control('start')"><Play :size="14"/>{{tr('开始自动清洗','Start cleanup')}}</button><button v-else-if="enabled" class="button ghost compact" :disabled="busy||uncertain" data-cleanup-action="pause" @click="control('pause')"><Pause :size="14"/>{{tr('暂停','Pause')}}</button><button v-else class="button primary compact" :disabled="busy||uncertain" data-cleanup-action="resume" @click="control('resume')"><Play :size="14"/>{{tr('继续本轮清洗','Continue this cleanup')}}</button></div>
 <p class="cleanup-policy">{{tr('保留原始资产、种子和历史，不改变已授权探测范围，不调用 Hunter。AI 意见必须结合域名对应的事实证据，排除操作按批记录，可撤销。','Keeps original assets, seeds and history, preserves probing scope and does not use Hunter. AI opinions require domain-bound evidence; exclusions are recorded and reversible.')}}</p>
 <template v-if="data"><div class="cleanup-state" role="status"><strong>{{label(data.phase)}}</strong><span>{{data.reason}}</span></div><progress v-if="data.phase==='preparing'" :value="percent" max="100" :aria-label="tr('全量种子整理进度','Whole-project seed preparation')"/>
 <div class="cleanup-inventory"><span>{{tr('原始索引','Raw index')}} <b>{{number(data.snapshot?.rawIndexSeeds)}}</b></span><span>{{tr('项目台账','Project ledger')}} <b>{{number(data.snapshot?.projectLedgerSeeds)}}</b></span><span>{{tr('按域名族整理为','Grouped into domain families')}} <b>{{number(data.snapshot?.groups)}}</b> {{tr('组','groups')}}</span><span v-if="localReview.pending>0" data-testid="cleanup-local-progress">{{tr('本地已复核','Locally reviewed')}} <b>{{number(localReview.done)}} / {{number(localReview.total)}}</b> {{tr('组','groups')}}</span></div>
 <div class="cleanup-metrics" data-testid="cleanup-decisions"><span v-if="localReview.pending>0">{{tr('本地待复核','Awaiting local review')}} <b>{{number(localReview.pending)}}</b></span><span>{{tr('保留相关','Related leads retained')}} <b>{{number(counts.retained||0)}}</b></span><span>{{tr('可撤销排除','Reversibly excluded')}} <b>{{number(counts.excluded||0)}}</b></span><span>{{tr('系统继续补证','Automatic evidence research')}} <b>{{number(counts.needs_evidence??counts.evidence??0)}}</b></span><span>{{tr('保留原决定 / 关联待证','Prior decisions / linked evidence pending')}} <b>{{number(counts.held||0)}}</b></span><span>{{tr('冲突需审核','Conflicts to review')}} <b>{{number(counts.conflict||0)}}</b></span></div>
 <p v-if="localReview.pending>0" class="cleanup-policy">{{tr('本地待复核由系统自动处理，与公开补证队列分别计数；索引已整理不代表全部种子已完成判断。','Local review runs automatically and is counted separately from public research. A prepared index does not mean every seed has been assessed.')}}</p>
 <div v-if="runId" class="cleanup-processing" data-testid="cleanup-processing"><p><strong>{{tr('AI 分析','AI analysis')}}</strong><span>{{tr('模型请求','Model requests')}} {{number(data.model?.requests||0)}}<template v-if="data.model?.pendingGroups!==undefined"> · {{tr('可分析证据组','Evidence groups ready for analysis')}} {{number(data.model.pendingGroups)}}</template> · Token {{number(data.model?.inputTokens||0)}} / {{number(data.model?.outputTokens||0)}}<template v-if="data.model?.unknownRequests"> · {{tr('结果未知，不重放','Unconfirmed, never replayed')}} {{data.model.unknownRequests}}</template></span></p><p><strong>{{tr('公开补证','Public evidence research')}}</strong><span>{{tr('已完成步骤','Completed steps')}} {{number(data.research?.completed||0)}} · {{tr('待完成步骤','Remaining steps')}} {{number(data.research?.pending||0)}}<template v-if="data.research?.running!==undefined"> · {{tr('执行中','Running')}} {{number(data.research.running)}}</template><template v-if="data.research?.retrying!==undefined"> · {{tr('退避重试','Retrying after backoff')}} {{number(data.research.retrying)}}</template> · {{tr('Hunter 请求','Hunter requests')}} {{number(data.hunterRequests??0)}}</span></p><p v-if="enabled&&data.research?.providerWaits?.length" data-testid="cleanup-provider-waits"><strong>{{tr('来源退避','Provider backoff')}}</strong><span v-for="wait in data.research.providerWaits" :key="wait.provider">{{wait.provider==='ct'?'CT':wait.provider==='dns'?'DNS':wait.provider}} · {{tr('自动恢复时间','Resumes automatically at')}} {{retryTime(wait.nextAt)}}</span></p></div>
 <details v-if="data.research?.recentErrors?.length" class="cleanup-network-errors" data-testid="cleanup-public-errors"><summary>{{tr('公开来源暂未补齐 · 最近异常与自动重试','Public evidence incomplete · recent errors and automatic retry')}} ({{data.research.recentErrors.length}})</summary><p class="cleanup-policy">{{tr('以下是 DNS / CT 等公开来源的补证记录，不是 AI 判断全部失败，也不是归属冲突。超时、502、截断或无记录均不会作为排除依据。','These records concern public DNS / CT research, not failure of every AI decision or ownership conflicts. Timeouts, 502s, truncation and missing records never justify exclusion.')}} {{enabled?tr('其他可判定的组继续处理，缺证项保留断点。','Other groups continue; missing evidence retains its checkpoint.'):tr('当前任务已停止执行，进度与原始证据保留。','Execution is currently stopped; progress and original evidence are retained.')}}</p><article v-for="(entry,index) in data.research.recentErrors" :key="index"><strong>{{researchLabel(entry.kind)}} · {{entry.target}}</strong><p>{{entry.error}}</p><small>{{entry.kind}} · {{tr('已尝试','Attempts')}} {{entry.attempts}} · {{retryDescription(entry)}}</small></article></details>
 <div v-if="runId" class="cleanup-results"><div class="cleanup-results-heading"><select v-model="filter" :disabled="busy" :aria-label="tr('清洗结果','Cleanup results')"><option value="all">{{tr('全部处理结果','All results')}}</option><option value="conflict">{{tr('需要决定的冲突','Conflicts requiring a decision')}}</option><option value="excluded">{{tr('已自动排除','Automatically excluded')}}</option><option value="needs_evidence">{{tr('系统继续补证','Evidence research queue')}}</option><option value="held">{{tr('保留原决定 / 关联待证','Prior decisions / linked evidence pending')}}</option><option value="retained">{{tr('保留的线索','Retained leads')}}</option></select><button class="button ghost compact" :disabled="busy||uncertain||enabled||!data.batches?.some(b=>!b.restored&&!b.restoredAt)" data-cleanup-action="restore" @click="control('restore')"><RotateCcw :size="14"/>{{tr('撤销本轮排除','Undo this cleanup’s exclusions')}}</button></div>
 <article v-for="(item,index) in data.items||[]" :key="item.key||item.domain||index"><div><b>{{item.domain||item.key}}</b><span :class="item.status||item.state">{{label(item.status||item.state)}}</span></div><p>{{item.reason}}</p><details v-if="item.evidence||item.sources?.length"><summary>{{tr('查看核对依据','Verification evidence')}}</summary><pre>{{JSON.stringify(item.evidence||item.sources,null,2)}}</pre></details></article><p v-if="!data.items?.length" class="cleanup-policy">{{reading?tr('正在读取…','Loading…'):!resultsReady?tr('当前筛选结果尚未读取，请刷新进度重试；不会重复提交清洗操作。','Results for this filter are unavailable. Refresh progress to retry the read; cleanup commands will not be repeated.'):filter==='conflict'?tr('暂无需要人工决定的证据冲突。缺证项由系统继续处理，无需逐条点击。','No evidence conflicts require a decision. Missing evidence is handled automatically; no per-item clicks are needed.'):tr('此筛选下暂无结果。未完成的补证会保留断点。','No results for this filter. Unfinished evidence research retains its checkpoint.')}}</p><footer v-if="resultsReady"><span>{{page}} / {{pages}}</span><button class="button ghost compact" :disabled="reading||busy||page<=1" data-cleanup-action="previous" @click="changePage(page-1)"><ChevronLeft :size="14"/></button><button class="button ghost compact" :disabled="reading||busy||page>=pages" data-cleanup-action="next" @click="changePage(page+1)"><ChevronRight :size="14"/></button></footer></div></template>
 <p v-if="error" class="cleanup-error" role="alert">{{error}}</p><p v-if="uncertain" class="cleanup-error">{{tr('操作结果尚未确认，已阻止重复提交。可刷新进度核对，原始数据保留。','The operation outcome is unconfirmed; repeat submission is blocked. Refresh progress to reconcile it. Original data is retained.')}}</p>
</section>
</template>
<style scoped>
.cleanup-inventory{display:flex;flex-wrap:wrap;gap:6px 18px;margin:12px 0 8px;color:var(--muted);font-size:11px}.cleanup-inventory b{color:var(--text);font-variant-numeric:tabular-nums}.cleanup-processing{border:1px solid var(--line);border-radius:6px;padding:7px 10px;margin:10px 0;background:var(--app-bg,#fafbfc)}.cleanup-processing p{display:flex;flex-wrap:wrap;gap:4px 12px;font-size:11px;line-height:1.6;margin:3px 0;color:var(--muted)}.cleanup-processing strong{min-width:62px;color:var(--text);font-weight:550}.cleanup-processing span{min-width:0;overflow-wrap:anywhere}
.cleanup-panel{padding:16px;border:1px solid var(--line);border-radius:10px;margin:0 0 16px;background:var(--card,#fff);min-width:0}.cleanup-panel header,.cleanup-start,.cleanup-results-heading,.cleanup-state,.cleanup-metrics,.cleanup-results footer{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.cleanup-panel header{justify-content:space-between;align-items:flex-start}.cleanup-panel h3{margin:0;font-size:14px}.cleanup-panel header p,.cleanup-policy{font-size:11px;color:var(--muted);line-height:1.65;margin:5px 0 12px}.cleanup-start{margin-top:12px;align-items:flex-end}.cleanup-start label{display:grid;gap:6px;flex:1 1 280px;font-size:11px;min-width:0}.cleanup-start input{width:100%;box-sizing:border-box;min-height:36px;padding:8px 10px}.cleanup-panel button{white-space:normal;min-height:34px}.cleanup-state{margin-top:12px;font-size:12px}.cleanup-state span{color:var(--muted);overflow-wrap:anywhere}.cleanup-panel progress{width:100%;height:6px;margin-top:12px;accent-color:var(--accent,#2874ff)}.cleanup-metrics{margin:12px 0;font-size:11px;gap:6px}.cleanup-metrics>span{border:1px solid var(--line);padding:7px 10px;border-radius:6px;color:var(--muted)}.cleanup-metrics b{margin-left:5px;color:var(--text)}.cleanup-results{border-top:1px solid var(--line);padding-top:10px}.cleanup-results-heading{justify-content:space-between}.cleanup-results-heading select{min-height:34px;max-width:100%}.cleanup-results article{border-top:1px solid var(--line);padding:11px 0;font-size:11px;margin-top:10px;overflow-wrap:anywhere}.cleanup-results article>div{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.cleanup-results article p{color:var(--muted);margin:5px 0}.cleanup-results details{color:var(--muted)}.cleanup-results summary{cursor:pointer}.cleanup-results pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:260px;overflow:auto}.cleanup-results footer{justify-content:flex-end;font-size:11px;margin-top:8px}.cleanup-results footer>span{margin-right:auto}.cleanup-network-errors{font-size:11px;margin:10px 0;color:var(--muted)}.cleanup-network-errors summary{cursor:pointer}.cleanup-network-errors article{padding:8px 0;overflow-wrap:anywhere}.cleanup-network-errors p{margin:4px 0}.cleanup-error{color:#a04733;font-size:11px;overflow-wrap:anywhere}.excluded{color:#7b6262}.conflict{color:#b56d00}.retained{color:#258365}@media(max-width:680px){.cleanup-panel{padding:12px}.cleanup-start>button{width:100%}.cleanup-results-heading{align-items:stretch}.cleanup-results-heading>*{flex:1 1 200px}}
</style>
